module protocol::obligation_query;

use sui::clock::Clock;

use protocol::market::Market;
use x_oracle::user_oracle::get_price;
use x_oracle::x_oracle::XOracle;
use protocol::coin_decimals_registry::CoinDecimalsRegistry;

use protocol::query_types::{Self, AssetBorrow, AssetDeposit};

public struct ObligationData has drop, copy {
    emode_group_id: u8,
    borrows: vector<AssetBorrow>,
    deposits: vector<AssetDeposit>,
}

public fun get_obligation_assets<MarketType>(
    market: &Market<MarketType>,
    obligation_id: ID
): (vector<std::type_name::TypeName>, vector<std::type_name::TypeName>) {
    let obligation = market.borrow_obligation<MarketType>(obligation_id);
    (obligation.debt_types(), obligation.deposit_types())
}

public fun get_obligation_detail<MarketType>(
    market: &Market<MarketType>,
    obligation_id: ID,
    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
): ObligationData {
    let obligation = market.borrow_obligation<MarketType>(obligation_id);

    let mut i = 0;

    let deposit_types = obligation.deposit_types();
    let mut collaterals_data = vector::empty<AssetDeposit>();

    let oracle = market.emode_registry().borrow_emode_group(obligation.emode_group()).get_oracle_base_token();

    while (i < deposit_types.length()) {
        let deposit_type = *vector::borrow(&deposit_types, i);

        collaterals_data.push_back(query_types::new_asset_collateral_from_ctoken(
            deposit_type,
            obligation.ctoken_amount_by_coin(deposit_type),
            get_price(x_oracle, deposit_type, oracle, clock),
            coin_decimals_registry.decimals(deposit_type),
            market.reserve_by_type(deposit_type).exchange_rate(),
        ));

        i = i + 1;
    };

    i = 0;

    let debt_types = obligation.debt_types();
    let mut debts_data = vector::empty<AssetBorrow>();

    while (i < debt_types.length()) {
        let debt_type = *debt_types.borrow(i);

        let market_borrow_index = market.reserve_by_type(debt_type).borrow_index().value();

        let debt = obligation.debt(debt_type);
        debts_data.push_back(query_types::new_asset_borrow(
            debt_type,
            debt.debt(market_borrow_index).floor(),
            get_price(x_oracle, debt_type, oracle, clock),
            coin_decimals_registry.decimals(debt_type),
            *debt.borrow_index(),
        ));

        i = i + 1;
    };

    ObligationData {
        emode_group_id: obligation.emode_group(),
        borrows: debts_data,
        deposits: collaterals_data,
    }
}

