module protocol::market_query;

use std::type_name::TypeName;
use sui::clock::Clock;

use protocol::coin_decimals_registry::CoinDecimalsRegistry;

use protocol::market::Market;
use protocol::asset::AssetConfig;
use protocol::interest::InterestModel;
use x_oracle::user_oracle::get_price;
use protocol::query_types::{Self, AssetBorrow, AssetDeposit};
use protocol::value::clock_now;
use x_oracle::x_oracle::XOracle;
use math::float::{Self, Decimal};

public struct AssetData has drop, copy {
    coin_type: TypeName,

    interest_model: InterestModel,
    utilization_rate: Decimal,

    borrow_paused: bool,
    deposit_paused: bool,
    withdraw_paused: bool,
    liquidation_paused: bool,
    flash_loan_paused: bool,

    reserve: u64,

    asset_setting: AssetConfig,

    // deposit and borow usage
    deposit_usage: AssetDeposit,
    borrow_usage: AssetBorrow,
}

fun get_asset_detail_inner<MarketType>(
    market: &Market<MarketType>,
    emode_group: u8,
    asset_type: TypeName,
    coin_decimals_registry: &CoinDecimalsRegistry,
    price: Decimal,
    clock: &Clock,
): AssetData {
    let asset = market.asset_by_type(asset_type);
    let reserve = market.reserve_by_type(asset_type);

    // fetch util data
    let exchange_rate = reserve.exchange_rate();
    let total_deposit = reserve.cash_plus_borrows_minus_reserves().floor();

    let decimals = coin_decimals_registry.decimals(asset_type);

    // deposit related data
    let deposit_usage = query_types::new_asset_deposit(
        asset_type,
        false,
        total_deposit,
        price,
        decimals,
        exchange_rate,
    );

    let now = clock_now(clock);

    // borrow related data
    let interest_rate = asset.interest_model().calc_interest(reserve.util_rate());
    let borrow_index = reserve.calculate_borrow_index<MarketType>(interest_rate, now);

    let total_debt = market.emode_registry().borrow_emode_group(emode_group).borrow_amount(asset_type).floor();

    let asset_setting = *asset.asset_config();
    let borrow_usage = query_types::new_asset_borrow(asset_type, total_debt, price, decimals, borrow_index);

    let interest_model = *asset.interest_model();
    let utilization_rate = reserve.util_rate();

    let borrow_paused =  asset.borrow_paused();
    let deposit_paused =  asset.deposit_paused();
    let withdraw_paused =  asset.withdraw_paused();
    let liquidation_paused =  asset.liquidation_paused();
    let flash_loan_paused =  asset.flash_loan_paused();

    let data = AssetData {
        coin_type: asset_type,
        interest_model,
        utilization_rate,

        borrow_paused,
        deposit_paused,
        withdraw_paused,
        liquidation_paused,
        flash_loan_paused,

        reserve: reserve.protocol_reserve<MarketType>(),

        asset_setting,
        deposit_usage,
        borrow_usage,
    };
    data
}

public fun get_asset_detail<MarketType>(
    market: &Market<MarketType>,
    emode_group: u8,
    asset_type: TypeName,
    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
): AssetData {
    let oracle = market.emode_registry().borrow_emode_group(emode_group).get_oracle_base_token();
    let price = get_price(x_oracle, asset_type, oracle, clock);
    get_asset_detail_inner<MarketType>(market, emode_group, asset_type, coin_decimals_registry, price, clock)
}

public fun get_asset_detail_no_price<MarketType>(
    market: &Market<MarketType>,
    emode_group: u8,
    asset_type: TypeName,
    coin_decimals_registry: &CoinDecimalsRegistry,
    clock: &Clock,
): AssetData {
    let price = float::zero();
    get_asset_detail_inner<MarketType>(market, emode_group, asset_type, coin_decimals_registry, price, clock)
}

